        P(198 * TS + 8, 6 * TS + 4, 120, 14, '#1a1e28'); DD.text('3.6L V6   485 HP', 198 * TS + 68 - cxp, 6 * TS + 8 - cyp, '#ffd88a', 1, null, 'center');
